// HOME HERO SECTION + NAV SATRT
// Minimal 2s Hover Hold + Outside Click Close for Tools Megamenu Start
const toolsNavItem = document.getElementById("toolsNavItem");
const toolsLink = document.getElementById("toolsLink");
const toolsMegaMenu = document.getElementById("toolsMegaMenu");
let holdTimer;

if (toolsNavItem && toolsLink && toolsMegaMenu) {
  const showTools = () => {
    clearTimeout(holdTimer);
    toolsLink.style.setProperty("background", "#000", "important");
    toolsLink.style.setProperty("color", "#fff", "important");
    toolsLink.style.setProperty("animation", "none", "important");
    Object.assign(toolsMegaMenu.style, {
      opacity: "1",
      visibility: "visible",
      pointerEvents: "auto",
      transform: "translateX(-50%) translateY(0)",
    });
  };

  const hideTools = () => {
    clearTimeout(holdTimer);
    ["background", "color", "animation"].forEach((p) =>
      toolsLink.style.removeProperty(p),
    );
    Object.assign(toolsMegaMenu.style, {
      opacity: "",
      visibility: "",
      pointerEvents: "",
      transform: "",
    });
  };

  // Hover open & 2-second delayed close
  toolsNavItem.addEventListener("mouseenter", showTools);
  toolsMegaMenu.addEventListener("mouseenter", showTools);
  toolsNavItem.addEventListener("mouseleave", () => {
    holdTimer = setTimeout(hideTools, 2000);
  });
  toolsMegaMenu.addEventListener("mouseleave", () => {
    holdTimer = setTimeout(hideTools, 2000);
  });

  // Instant close when clicking outside or clicking a tool inside
  document.addEventListener("click", (e) => {
    if (
      !toolsNavItem.contains(e.target) ||
      e.target.closest("#toolsMegaMenu a")
    )
      hideTools();
  });
}
// Minimal 2s Hover Hold + Outside Click Close for Tools Megamenu end

document.addEventListener("DOMContentLoaded", () => {
  // 1. Searchable Database
  const searchItems = [
    {
      title: "PNG to JPG Converter",
      category: "Tools",
      desc: "Convert PNG images with lossless colors",
      icon: "fa-image",
      tag: "Converter",
    },
    {
      title: "JPG to WebP Tool",
      category: "Tools",
      desc: "Optimize JPG images into lightweight WebP format",
      icon: "fa-bolt",
      tag: "High Speed",
    },
    {
      title: "WebP to PNG Converter",
      category: "Tools",
      desc: "Restore transparency and edit WebP graphics",
      icon: "fa-wand-magic-sparkles",
      tag: "Popular",
    },
    {
      title: "Bulk Image Compressor",
      category: "Tools",
      desc: "Reduce picture size without visible quality loss",
      icon: "fa-compress",
      tag: "Offline",
    },
    {
      title: "Beginner SEO Guide - Step-by-Step",
      category: "Blog",
      desc: "Complete pillar guide to mastering organic search",
      icon: "fa-book-open",
      tag: "Pillar",
    },
    {
      title: "What Are Backlinks In SEO?",
      category: "Blog",
      desc: "16 proven techniques for building site authority",
      icon: "fa-link",
      tag: "Cluster",
    },
    {
      title: "SEO Vs SEM Differences",
      category: "Blog",
      desc: "10 crucial factors deciding paid vs organic marketing",
      icon: "fa-chart-pie",
      tag: "Marketing",
    },
    {
      title: "Privacy & Client-Side Processing",
      category: "Pages",
      desc: "Learn why zero files ever reach any remote server",
      icon: "fa-shield-halved",
      tag: "Trust",
    },
    {
      title: "About Aiofoct Engineering",
      category: "Pages",
      desc: "Fast, secure, and private web-based digital utilities",
      icon: "fa-user-group",
      tag: "Company",
    },
  ];

  // 2. Search Modal Elements
  const searchModal = document.getElementById("searchModal");
  const openSearchBtn = document.getElementById("openSearchBtn");
  const mobileSearchTrigger = document.getElementById("mobileSearchTrigger");
  const closeSearchBtn = document.getElementById("closeSearchBtn");
  const searchInput = document.getElementById("searchInput");
  const searchResultsList = document.getElementById("searchResultsList");

  function renderSearchResults(query = "") {
    const cleanQuery = query.toLowerCase().trim();
    const filtered = searchItems.filter(
      (item) =>
        item.title.toLowerCase().includes(cleanQuery) ||
        item.desc.toLowerCase().includes(cleanQuery) ||
        item.category.toLowerCase().includes(cleanQuery),
    );

    searchResultsList.innerHTML = "";

    if (filtered.length === 0) {
      searchResultsList.innerHTML = `
            <div style="text-align: center; padding: 32px 16px; color: #94a3b8;">
              <i class="fa-regular fa-face-frown" style="font-size: 2rem; margin-bottom: 8px;"></i>
              <p>No results found for "${query}". Try searching "PNG", "SEO", or "Compress".</p>
            </div>
          `;
      return;
    }

    const groups = {};
    filtered.forEach((item) => {
      if (!groups[item.category]) groups[item.category] = [];
      groups[item.category].push(item);
    });

    for (const [category, items] of Object.entries(groups)) {
      const catTitle = document.createElement("div");
      catTitle.className = "search-category-title";
      catTitle.innerHTML = `<i class="fa-solid fa-layer-group" style="font-size: 0.7rem; color: #7FB800;"></i> ${category}`;
      searchResultsList.appendChild(catTitle);

      items.forEach((item) => {
        const row = document.createElement("div");
        row.className = "search-result-item";
        row.innerHTML = `
              <div class="search-item-left">
                <i class="fa-solid ${item.icon}"></i>
                <div>
                  <strong style="display:block; font-size: 0.92rem;">${item.title}</strong>
                  <span style="font-size: 0.76rem; color: #64748b;">${item.desc}</span>
                </div>
              </div>
              <span class="search-tag-badge">${item.tag}</span>
            `;
        row.addEventListener("click", () => {
          closeModal();
        });
        searchResultsList.appendChild(row);
      });
    }
  }

  function openModal() {
    searchModal.classList.add("active");
    searchInput.value = "";
    renderSearchResults("");
    setTimeout(() => searchInput.focus(), 60);
  }

  function closeModal() {
    searchModal.classList.remove("active");
  }

  openSearchBtn.addEventListener("click", openModal);
  if (mobileSearchTrigger) {
    mobileSearchTrigger.addEventListener("click", () => {
      closeDrawer();
      openModal();
    });
  }
  closeSearchBtn.addEventListener("click", closeModal);

  searchModal.addEventListener("click", (e) => {
    if (e.target === searchModal) closeModal();
  });

  window.addEventListener("keydown", (e) => {
    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
      e.preventDefault();
      searchModal.classList.contains("active") ? closeModal() : openModal();
    }
    if (e.key === "Escape" && searchModal.classList.contains("active")) {
      closeModal();
    }
  });

  searchInput.addEventListener("input", (e) => {
    renderSearchResults(e.target.value);
  });

  // 3. ZERO-SHIFT TYPEWRITER ANIMATION
  const typingElem = document.getElementById("typingNeed");
  if (typingElem) {
    const targetWord = "need";
    let currentIndex = 0;
    let isDeleting = false;

    typingElem.textContent = "";

    function runTypewriter() {
      if (!isDeleting) {
        currentIndex++;
        typingElem.textContent = targetWord.substring(0, currentIndex);

        if (currentIndex === targetWord.length) {
          isDeleting = true;
          setTimeout(runTypewriter, 2400); // 2.4s pause when fully typed
          return;
        }
        setTimeout(runTypewriter, 150);
      } else {
        currentIndex--;
        typingElem.textContent = targetWord.substring(0, currentIndex);

        if (currentIndex === 0) {
          isDeleting = false;
          setTimeout(runTypewriter, 450); // Pause before re-typing
          return;
        }
        setTimeout(runTypewriter, 90);
      }
    }

    setTimeout(runTypewriter, 700);
  }

  // 4. Interactive Convert Button
  const demoBtn = document.getElementById("demoConvertBtn");
  const btnText = document.getElementById("btnConvertText");
  const btnIcon = document.getElementById("btnConvertIcon");
  const chipExt = document.getElementById("chipExt");
  const chipMeta = document.getElementById("chipMeta");

  demoBtn.addEventListener("click", () => {
    btnText.textContent = "Processing...";
    btnIcon.className = "fa-solid fa-spinner fa-spin";
    demoBtn.style.opacity = "0.8";

    setTimeout(() => {
      btnText.textContent = "Converted!";
      btnIcon.className = "fa-solid fa-check";
      chipExt.textContent = "PNG";
      chipMeta.textContent = "1.8 MB · Finished locally in browser";
      demoBtn.style.backgroundColor = "#10b981";
      demoBtn.style.color = "#ffffff";

      setTimeout(() => {
        btnText.textContent = "Convert";
        btnIcon.className = "fa-solid fa-bolt";
        chipExt.textContent = "JPG";
        chipMeta.textContent = "2.4 MB · converting to PNG";
        demoBtn.style.backgroundColor = "";
        demoBtn.style.color = "";
        demoBtn.style.opacity = "1";
      }, 3200);
    }, 1100);
  });

  // 5. Mobile Drawer & Accordion Functionality
  const hamburgerBtn = document.getElementById("hamburgerBtn");
  const mobileDrawer = document.getElementById("mobileDrawer");
  const mobileDrawerBackdrop = document.getElementById("mobileDrawerBackdrop");
  const closeDrawerBtn = document.getElementById("closeDrawerBtn");
  const mobileToolsTrigger = document.getElementById("mobileToolsTrigger");
  const mobileToolsAccordion = document.getElementById("mobileToolsAccordion");
  const closeDrawerItems = document.querySelectorAll(".close-drawer-item");

  function openDrawer() {
    mobileDrawer.classList.add("active");
    mobileDrawerBackdrop.classList.add("active");
  }

  function closeDrawer() {
    mobileDrawer.classList.remove("active");
    mobileDrawerBackdrop.classList.remove("active");
  }

  hamburgerBtn.addEventListener("click", openDrawer);
  closeDrawerBtn.addEventListener("click", closeDrawer);
  mobileDrawerBackdrop.addEventListener("click", closeDrawer);

  closeDrawerItems.forEach((item) => {
    item.addEventListener("click", closeDrawer);
  });

  mobileToolsTrigger.addEventListener("click", () => {
    mobileToolsTrigger.classList.toggle("active");
    mobileToolsAccordion.classList.toggle("open");
  });
});
// HOME HERO SECTION + NAV END

// HOME SECTION 6 FAQ START
document.addEventListener('DOMContentLoaded', function () {
  var items = document.querySelectorAll('.faq-item');

  // Expand whichever item starts with the is-open class (e.g. the
  // first question) now that its real height can be measured
  items.forEach(function (item) {
    if (item.classList.contains('is-open')) {
      var openAnswer = item.querySelector('.faq-answer');
      openAnswer.style.maxHeight = openAnswer.scrollHeight + 'px';
    }
  });

  items.forEach(function (item) {
    var button = item.querySelector('.faq-question');
    var answer = item.querySelector('.faq-answer');

    button.addEventListener('click', function () {
      var isOpen = item.classList.contains('is-open');

      // Close any other open item (accordion behavior — remove this
      // block if you want multiple answers open at once)
      items.forEach(function (other) {
        if (other !== item && other.classList.contains('is-open')) {
          other.classList.remove('is-open');
          other.querySelector('.faq-question').setAttribute('aria-expanded', 'false');
          other.querySelector('.faq-answer').style.maxHeight = null;
        }
      });

      if (isOpen) {
        item.classList.remove('is-open');
        button.setAttribute('aria-expanded', 'false');
        answer.style.maxHeight = null;
      } else {
        item.classList.add('is-open');
        button.setAttribute('aria-expanded', 'true');
        answer.style.maxHeight = answer.scrollHeight + 'px';
      }
    });
  });
});
// HOME SECTION 6 FAQ END

// FOOTER SMOOTH BACK TO TOP START
document.addEventListener('DOMContentLoaded', () => {
  // Smooth Back to Top
  const backToTopBtn = document.getElementById('backToTopBtn');
  if (backToTopBtn) {
    backToTopBtn.addEventListener('click', () => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

  // Copy Site URL with instant confirmation icon
  const copyLinkBtn = document.getElementById('copySiteLinkBtn');
  if (copyLinkBtn) {
    copyLinkBtn.addEventListener('click', () => {
      if (navigator.clipboard) {
        navigator.clipboard.writeText(window.location.href).then(() => {
          const icon = copyLinkBtn.querySelector('i');
          icon.className = 'fa-solid fa-check';
          copyLinkBtn.style.backgroundColor = 'var(--brand-lime-2)';
          copyLinkBtn.style.color = '#15150F';

          setTimeout(() => {
            icon.className = 'fa-solid fa-link';
            copyLinkBtn.style.backgroundColor = '';
            copyLinkBtn.style.color = '';
          }, 1800);
        });
      }
    });
  }
});
// FOOTER SMOOTH BACK TO TOP END